import { pool } from "../pg";

export async function countPostsPerTag(tags: string[]): Promise<Record<string, number>> {
  const counts = await Promise.all(
    tags.map((tag) =>
      pool.query("SELECT count(*)::int AS n FROM post_tags WHERE tag = $1", [tag]).then((r) => r.rows[0].n),
    ),
  );
  return Object.fromEntries(tags.map((t, i) => [t, counts[i]]));
}

