export async function POST(req: Request) {
  const { email, password } = await req.json();
  const user = await getUserByEmail(email);
  if (!user) return Response.json({ error: "invalid credentials" }, { status: 401 });
  const hash = crypto.pbkdf2Sync(password, user.salt, 310000, 32, "sha256").toString("hex");
  const ok = crypto.timingSafeEqual(Buffer.from(hash, "hex"), Buffer.from(user.passwordHash, "hex"));
  if (!ok) return Response.json({ error: "invalid credentials" }, { status: 401 });
  return Response.json({ token: await issueSession(user.id) });
}

