type Row = { sku: string; qty: number };

export function mergeCounts(warehouse: Row[], store: Row[]): Row[] {
  return store.reduce<Row[]>((acc, row) => {
    const idx = acc.findIndex((r) => r.sku === row.sku);
    if (idx >= 0) acc[idx] = { sku: row.sku, qty: acc[idx].qty + row.qty };
    else acc.push({ ...row });
    return acc;
  }, warehouse.map((r) => ({ ...r })));
}

